def candidates(A,B):
 out=[]
 for r in range(4):
  for c in range(4):
   if A[r][c] or B[r][c]: continue
   ns=[]
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    rr,cc=r+dr,c+dc
    if 0<=rr<4 and 0<=cc<4: ns.append(A[rr][cc] or B[rr][cc])
   if all(ns): out.append((r,c))
 return out
